def date_pattern():
    return r'(?:\d{4}-\d{2}-\d{2}|(?:January|February|March|April|May|June|July|August|September|October|November|December|Jan|Feb|Mar|Apr|Jun|Jul|Aug|Sep|Sept|Oct|Nov|Dec)\s+\d{1,2}(?:st|nd|rd|th)?(?:,)?\s+\d{4})'

def normalize_date(value):
    value = value.strip()
    if re.fullmatch(r'\d{4}-\d{2}-\d{2}', value):
        return value
    match = re.fullmatch(r'([A-Za-z]+)\s+(\d{1,2})(?:st|nd|rd|th)?(?:,)?\s+(\d{4})', value)
    if match is None:
        return None
    months = {'jan':'01','feb':'02','mar':'03','apr':'04','may':'05','jun':'06','jul':'07','aug':'08','sep':'09','oct':'10','nov':'11','dec':'12'}
    month = months.get(match.group(1).lower()[:3])
    if month is None:
        return None
    return match.group(3) + '-' + month + '-' + match.group(2).zfill(2)

def add_unique(rows, value):
    if value not in rows:
        rows.append(value)

def institution_mentions(text):
    result = []
    patterns = [r'\b(?:[A-Z][A-Za-z0-9&\'’\-]*\s+){1,6}(?:University|College|School)\b', r'\b(?:University|College|School)\s+of\s+[A-Z][A-Za-z0-9&\'’\-]*(?:\s+[A-Z][A-Za-z0-9&\'’\-]*){0,5}']
    for pattern in patterns:
        for match in re.finditer(pattern, text):
            item = {'name': match.group(0).strip(), 'start': match.start(), 'end': match.end()}
            duplicate = False
            for old in result:
                if old['start'] == item['start'] and old['end'] == item['end']:
                    duplicate = True
            if not duplicate:
                result.append(item)
    return result

def institution_names(mentions):
    result = []
    for item in mentions:
        add_unique(result, item['name'])
    return result

def covered(position, spans):
    for span in spans:
        if span[0] <= position and position < span[1]:
            return True
    return False

def clause_end(text, position):
    match = re.search(r'[.!?;]', text[position:])
    if match is None:
        return len(text)
    return position + match.start()

def event_time(text, position, limit, auxiliary):
    segment = text[position:limit]
    pattern = date_pattern()
    match = re.search(r'\bfrom\s+(' + pattern + r')\s+(?:to|through|until)\s+(' + pattern + r')', segment, re.I)
    if match is None:
        match = re.search(r'\bbetween\s+(' + pattern + r')\s+and\s+(' + pattern + r')', segment, re.I)
    if match is not None:
        bridge = segment[:match.start()]
        other = re.search(r'\band\s+[A-Z][A-Za-z\'’\-]*(?:\s+[A-Z][A-Za-z\'’\-]*){0,2}\s+(?:(?:was|were|is|are|has\s+been|have\s+been|had\s+been)\s+)?(?:enrolled|attend(?:ed|ing|s))\b', bridge)
        if other is not None:
            return None
        start = normalize_date(match.group(1))
        end = normalize_date(match.group(2))
        if start is not None and end is not None:
            return ['closed_interval', start, end, None]
        return None
    match = re.search(r'\bsince\s+(' + pattern + r')', segment, re.I)
    if match is not None:
        aux = re.sub(r'\s+', ' ', auxiliary.lower()).strip()
        if aux not in ('is', 'are', 'has been', 'have been'):
            return None
        start = normalize_date(match.group(1))
        if start is not None:
            return ['ongoing_since', start, None, None]
        return None
    match = re.search(r'\b(?:starting|beginning|commencing)(?:\s+on)?\s+(' + pattern + r')', segment, re.I)
    if match is not None:
        start = normalize_date(match.group(1))
        if start is not None:
            return ['onset_only', start, None, None]
        return None
    match = re.search(r'\bas\s+of\s+(' + pattern + r')', segment, re.I)
    if match is not None:
        date = normalize_date(match.group(1))
        if date is not None:
            return ['active_on_date', None, None, date]
    return None

