    if since is not None:
        aux = re.sub(r'\s+', ' ', auxiliary.lower()).strip()
        if aux not in ('is', 'are', 'has been', 'have been'):
            return None
        first = iso_date(since.group(1))
        if first is not None:
            return ['ongoing_since', first, None, None]
        return None
    onset = re.search(r'\b(?:starting|beginning|commencing)(?:\s+on)?\s+(' + date + r')', tail, re.I)
